public class Solution {
    static int lis(int[] nums) {
        int[] tails = new int[nums.length];
        int tam = 0;
        for (int x : nums) {
            int lo = 0, hi = tam; // primeiro tails[k] >= x (estrita: igual substitui)
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < x) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = x;
            if (lo == tam) tam++;
        }
        return tam;
    }
}

