import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static int quadratica(int[] a) {
        int[] dp = new int[a.length];
        int melhor = 0;
        for (int i = 0; i < a.length; i++) {
            dp[i] = 1;
            for (int j = 0; j < i; j++) if (a[j] < a[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
            melhor = Math.max(melhor, dp[i]);
        }
        return melhor;
    }

    @Test void exemplos() {
        assertEquals(4, Solution.lis(new int[]{10, 9, 2, 5, 3, 7, 101, 18}));
        assertEquals(1, Solution.lis(new int[]{7, 7, 7}));
        assertEquals(0, Solution.lis(new int[]{}));
    }

    @Test void aleatorio() {
        var rnd = new Random(9);
        for (int t = 0; t < 300; t++) {
            int[] a = rnd.ints(rnd.nextInt(40), 0, 15).toArray();
            assertEquals(quadratica(a), Solution.lis(a), Arrays.toString(a));
        }
    }

    @Test void grande() {
        int[] a = new int[200_000];
        for (int i = 0; i < a.length; i++) a[i] = i % 2 == 0 ? i : -i;
        assertEquals(100_000, Solution.lis(a));
    }
}

