public class Solution {
    static long lucro(int[] precos) {
        long segurando = Long.MIN_VALUE / 2, vendeu = 0, livre = 0;
        for (int p : precos) {
            long s = Math.max(segurando, livre - p);   // continua segurando ou compra (só se estava livre)
            long v = segurando + p;                     // vende hoje
            long l = Math.max(livre, vendeu);           // descansa (cooldown termina)
            segurando = s;
            vendeu = v;
            livre = l;
        }
        return Math.max(vendeu, livre);
    }
}

