import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static long bruta(int[] p, int i, boolean seg) {
        if (i >= p.length) return 0;
        long pular = bruta(p, i + 1, seg);
        if (seg) return Math.max(pular, p[i] + bruta(p, i + 2, false));
        return Math.max(pular, -p[i] + bruta(p, i + 1, true));
    }

    @Test void exemplos() {
        assertEquals(3, Solution.lucro(new int[]{1, 2, 3, 0, 2}));
        assertEquals(0, Solution.lucro(new int[]{5, 4, 3}));
        assertEquals(0, Solution.lucro(new int[]{}));
    }

    @Test void aleatorio() {
        var rnd = new Random(10);
        for (int t = 0; t < 300; t++) {
            int[] p = rnd.ints(rnd.nextInt(12), 0, 10).toArray();
            assertEquals(bruta(p, 0, false), Solution.lucro(p), Arrays.toString(p));
        }
    }
}
